/**
 * Fireflies shader.
 *
 * ## The mathematical idea
 *
 * One firefly per cell of a grid, its position drawn from the cell's hash,
 * its blinking a sine of its own phase — never a draw per frame, which
 * would produce nothing but noise. The halo is a decaying exponential of
 * the distance, summed over the nine neighbouring cells so that it crosses
 * its cell's edges.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the night background.
 * - `uColorB`, `uColorC` — the two firefly hues, spread by seed.
 * - `uSpeed` — rate of the blinking and of the drift.
 * - `uDensity` — number of cells across the shorter side.
 * - `uGlow` — reach of the halo.
 */
export const FIREFLIES_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSpeed;
uniform float uDensity;
uniform float uGlow;

// Pseudo-random number: projection onto an arbitrary direction, amplified
// sine, fractional part.
float fireflyHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Two decorrelated numbers for the same cell: the second is hashed from a
// shifted point, without which x and y would be tied together.
vec2 fireflyHash2(vec2 p) {
  return vec2(fireflyHash(p), fireflyHash(p + vec2(37.3, 17.7)));
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vec2(vUv.x * aspect, vUv.y) * max(uDensity, 1.0);
  float t = uTime * uSpeed;

  vec2 cell = floor(p);
  vec3 colour = uColorA;

  // The nine neighbouring cells: a halo overflows its cell, and without that
  // sweep it would be cut clean at every mesh edge.
  for (int dx = -1; dx <= 1; dx += 1) {
    for (int dy = -1; dy <= 1; dy += 1) {
      vec2 neighbour = cell + vec2(float(dx), float(dy));
      vec2 seed = fireflyHash2(neighbour);

      // The firefly drifts gently around its anchor point: two sines of
      // non-multiple frequencies, so that the orbit never closes exactly on
      // itself.
      vec2 centre = neighbour + 0.5
        + 0.28 * vec2(sin(t * 0.7 + seed.x * 6.28318), cos(t * 0.53 + seed.y * 6.28318));

      // Each firefly blinks at its own phase: the negative half of the sine is
      // crushed, for brief flashes separated by real nights.
      float phase = seed.x * 6.28318;
      float flash = pow(max(sin(t * 1.6 + phase), 0.0), 3.0);

      // Halo: an exponential of the distance, the profile of a point source
      // seen through the air.
      float d = length(p - centre);
      float halo = exp(-d * d / max(uGlow * uGlow * 0.18, 0.0005)) * flash;

      vec3 tint = mix(uColorB, uColorC, fireflyHash(neighbour + 11.0));
      colour += tint * halo;
    }
  }

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Fireflies: points blinking each at its own phase, in a soft halo.
 *
 * ## The principle
 *
 * One firefly per cell of a grid, its position drawn from the cell's hash; the blinking is a sine of its own phase, never a draw per frame.
 *
 * The halo is an exponential of the distance, summed over the nine neighbouring cells so as to cross the mesh edges.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its fallback.
 * Reading the tokens, converting them to floats and re-reading them when the
 * theme changes all come from the engine — copying them here would leave as
 * many versions to maintain as there are backgrounds.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface — it grants only one
 * per backend — and under reduced motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { FIREFLIES_FRAGMENT } from './fireflies.shader.js'

/** What the escape hatch receives. */
export interface FirefliesControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Properties specific to this component. */
export interface FirefliesOwnProps {
  /** Rate of the blinking and of the drift. @defaultValue 0.8 */
  speed?: number
  /** Number of cells across the shorter side. @defaultValue 16 */
  density?: number
  /** Reach of the halo. @defaultValue 0.6 */
  glow?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<FirefliesControls>
}

/** Every property. */
export type FirefliesProps = Customisable<FirefliesOwnProps>

/** Tokens used by default: the night, then the two firefly hues. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-amber-300',
  '--o-palette-lime-300',
] as const

/** Default fallback: a frozen hue, in the same tones. */
const DEFAULT_FALLBACK = 'o-bg-zinc-50 dark:o-bg-zinc-950'

/**
 * Fireflies.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Fireflies className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Fireflies({
  speed = 0.8,
  density = 16,
  glow = 0.6,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: FirefliesProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: FIREFLIES_FRAGMENT,
    colors,
    uniforms: { uSpeed: speed, uDensity: density, uGlow: glow },
    name: 'fireflies',
    // A wider mesh puts fewer fireflies on screen, hence fewer overlapping
    // halos: it is the setting that weighs, so it is the one that is capped.
    degrade: (quality) => ({
      uDensity: quality === 'low' ? Math.min(density, 10) : density,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
